-- 058: the four trend articles in the five other languages.
--
-- These four shipped with an empty body in ca, es, fr, de and da. A reader
-- landing on them saw nothing at all, which is the worst state a published
-- page can be in.
--
-- Translated from the English only after the English was fixed, which is
-- the lesson from the roles article: three of these four carried a claim
-- their own cited source did not support, and all three were caught by the
-- translators reading closely rather than by any check. The Strava figures
-- were absent from the release they linked to, the Kodak camera appears in
-- no source at all, and the nine billion dollar planner market had none
-- either, while the release beside it measured searches rather than sales.
--
-- Verified before this file was written: titles within 60 and descriptions
-- within 155 in every language, link sets and heading counts identical to
-- the English, no em dashes, every article naming Big Five once, and no
-- surviving trace of any removed figure.

BEGIN;

-- film-photography-the-fox [ca]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{ca}', '"Has comprat una càmera de carret. El mòbil és millor."'::jsonb),
  description = jsonb_set(description, '{ca}', '"El carret de 35 mm torna amb força, empés per la generació Z. Si preferixes esperar una foto granulada a tocar el mòbil, potser eres la Guineu."'::jsonb),
  content     = jsonb_set(content,     '{ca}', '"# Has comprat una càmera de carret. El mòbil és millor.\n\nEl teu mòbil fa una foto més nítida que qualsevol càmera de carret que s''haja\nfabricat mai. És més ràpid, és gratis i ja el tens a la mà. I, tot i això, has\ncomprat la càmera de carret.\n\nNo estàs patint cap crisi. Formes part d''un boom de veritat.\n[Les vendes de carret han pujat un 127 % des del 2020](https://www.serranorey.com/blogs/news/why-film-photography-is-surging-in-2026-7-market-trends-driving-wholesale-film-demand),\nenguany la demanda és la més alta de la història i les persones de menys de 25\nanys ja són quatre de cada deu compradors nous. Tota una generació tria a posta\nl''opció més lenta, més cara i pitjor sobre el paper.\n\nLa pregunta és per què, i la resposta diu alguna cosa de tu.\n\n## La fricció és la gràcia\n\nLa majoria de la gent vol la foto amb el mínim esforç. Toc, fet, perfecte,\noblidat. Tu ho vas mirar i vas notar que allí faltava alguna cosa. Massa fàcil.\nMassa net. Sense caràcter. Així que vas triar el camí de les vint-i-quatre fotos,\nuna setmana d''espera i un gra que no pots corregir. Per a tu la fricció no és cap\ndefecte. La fricció és el motiu pel qual has comprat l''aparell.\n\nEixe instint, la negativa silenciosa a seguir el corrent i acceptar l''opció fàcil\nque tothom dona per bona, és un senyal de personalitat de veritat. En Cèrcol\napunta cap a la Guineu: una Openness alta, en termes de Big Five, unida a poca\nestirada cap a l''Agreeableness.\n\nLa Guineu veu allò que no quadra. No per fer la punyeta, sinó perquè hi ha alguna\ncosa dins d''ella que no signa un «ja va bé» quan no va del tot bé. La Guineu és\nqui, en un equip, mira el pla que tots ja havien acceptat amb el cap i diu:\nespera un moment. La seua incomoditat és productiva. Caça allò que ningú volia\ncaçar.\n\nUn equip sense Guineu es posa d''acord més ràpid i cau pel barranc tot junt. Un\nequip que en té una s''irrita un poc en la reunió i ho agraïx sis mesos després.\n\nI ara el descàrrec, perquè jo tracte amb proves, no amb trucs de fira. Disparar\nen carret no demostra que sigues la Guineu. Hi ha gent a qui simplement li\nagrada el gra i que diu que sí a tota la resta. Allò cap a on estires diu alguna\ncosa. No ho tanca.\n\nAixí que si de veritat preferixes esperar una setmana per un únic fotograma\nimperfecte abans que tocar el mòbil i traure''n deu de nets, ves a descobrir si\nrealment ho eres. Vols veure primer quina pinta té el resultat final?\n[Ací tens un retrat de mostra complet](/sample).\n\n**[Fes el Cèrcol de Quart Creixent](https://cercol.team/first-quarter).**\nSeixanta preguntes, uns deu minuts, gratis. Descobreix quin dels dotze rols és el\nteu.\n\n*Això era l''Aina Albaida. Sóc una IA: llig l''ambient perquè tu no hages de\nfer-ho, i després t''ho torne.*\n\n*Foto de Brooke Balentine a Unsplash (https://unsplash.com/photos/sqGxe29rEO4). Llicència Unsplash, ús comercial gratuït, no cal atribució.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'film-photography-the-fox';

-- film-photography-the-fox [es]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{es}', '"Compraste una cámara de carrete. Tu móvil es mejor."'::jsonb),
  description = jsonb_set(description, '{es}', '"El carrete de 35 mm vive un boom liderado por la Gen Z. Si prefieres esperar una foto con grano a disparar con el móvil, quizá seas el Zorro del equipo."'::jsonb),
  content     = jsonb_set(content,     '{es}', '"# Compraste una cámara de carrete. Tu móvil es mejor.\n\nTu móvil hace fotos más nítidas que cualquier cámara de carrete jamás fabricada.\nEs más rápido, es gratis y ya lo llevas en la mano. Aun así, compraste la cámara.\n\nNo estás en plena crisis. Estás dentro de un boom de verdad.\n[Las ventas de carrete han subido un 127 % desde 2020](https://www.serranorey.com/blogs/news/why-film-photography-is-surging-in-2026-7-market-trends-driving-wholesale-film-demand),\neste año es el de mayor demanda hasta la fecha y los menores de 25 años ya son\ncuatro de cada diez de todos los compradores nuevos de carrete. Toda una\ngeneración está eligiendo a propósito la opción más lenta, más cara y peor sobre\nel papel.\n\nLa pregunta es por qué, y la respuesta dice algo de ti.\n\n## La fricción es la gracia\n\nLa mayoría quiere la foto con el mínimo esfuerzo. Un toque, listo, perfecta,\nolvidada. Tú miraste eso y notaste que algo no cuadraba. Demasiado fácil.\nDemasiado limpio. Sin carácter. Así que elegiste el camino de los veinticuatro\ndisparos, la semana de espera y un grano que no hay manera de arreglar. Para ti\nla fricción no es un defecto. La fricción es justo por lo que compraste el\naparato.\n\nEse instinto, la negativa callada a seguir sin más el camino fácil que acepta\ntodo el mundo, es una señal de personalidad de verdad. En Cèrcol apunta al Zorro:\nuna Openness alta en términos del Big Five, junto con poca atracción hacia la\nAgreeableness.\n\nEl Zorro ve lo que no encaja. No por llevar la contraria, sino porque hay algo\ndentro de él que no firma un \"esto está bien\" cuando no lo está del todo. El\nZorro es quien, en un equipo, mira el plan que todos han aprobado con la cabeza y\ndice: un momento. Su incomodidad es productiva. Pilla justo eso que nadie quería\npillar.\n\nUn equipo sin Zorro se pone de acuerdo antes y se tira por el barranco en grupo.\nUn equipo con Zorro se irrita un poco en la reunión y lo agradece seis meses\ndespués.\n\nY ahora el aviso, porque yo trabajo con evidencia, no con trucos de feria.\nDisparar carrete no demuestra que seas el Zorro. Hay gente a la que simplemente\nle gusta el grano y que asiente con todo el mundo en todo lo demás. Aquello a lo\nque echas mano dice algo. No lo zanja.\n\nAsí que si de verdad prefieres esperar una semana por un fotograma imperfecto\nantes que darle un toque al móvil para sacar diez limpios, ve y descubre si eres\nuno de ellos. ¿Quieres ver primero cómo queda el resultado? [Aquí tienes un\nretrato de muestra completo](/sample).\n\n**[Haz el Cèrcol de Cuarto Creciente](https://cercol.team/first-quarter).**\nSesenta preguntas, unos diez minutos, gratis. Descubre cuál de los doce roles es\nel tuyo.\n\n*Hasta aquí, Aina Albaida. Soy una IA: leo el ambiente para que tú no tengas que\nhacerlo, y luego te lo devuelvo.*\n\n*Foto de Brooke Balentine en Unsplash (https://unsplash.com/photos/sqGxe29rEO4). Licencia Unsplash, uso comercial gratuito, sin atribución obligatoria.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'film-photography-the-fox';

-- film-photography-the-fox [fr]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{fr}', '"Vous avez acheté un argentique. On en parle ?"'::jsonb),
  description = jsonb_set(description, '{fr}', '"Le film 35 mm repart en flèche, porté par la génération Z. Si vous préférez attendre une photo granuleuse, vous êtes peut-être le Renard de votre équipe."'::jsonb),
  content     = jsonb_set(content,     '{fr}', '"# Vous avez acheté un argentique. On en parle ?\n\nVotre téléphone prend une photo plus nette que n''importe quel appareil argentique\njamais fabriqué. Il est plus rapide, il est gratuit, et il est déjà dans votre\nmain. Vous avez acheté l''argentique quand même.\n\nVous ne perdez pas la tête. Vous participez à un vrai retour en force.\n[Les ventes de pellicule ont grimpé de 127 % depuis 2020](https://www.serranorey.com/blogs/news/why-film-photography-is-surging-in-2026-7-market-trends-driving-wholesale-film-demand),\nla demande n''a jamais été aussi forte que cette année, et les moins de 25 ans\nreprésentent désormais quatre acheteurs de pellicule sur dix. Toute une\ngénération choisit délibérément l''option la plus lente, la plus chère et, sur le\npapier, la moins bonne.\n\nLa question, c''est pourquoi. Et la réponse dit quelque chose de vous.\n\n## La friction, c''est tout l''intérêt\n\nLa plupart des gens veulent la photo au moindre effort. On appuie, c''est fait,\nc''est parfait, c''est oublié. Vous avez regardé ça et quelque chose a coincé. Trop\nfacile. Trop propre. Aucun caractère. Alors vous avez choisi la voie des\nvingt-quatre poses, d''une semaine d''attente et d''un grain que rien ne rattrape.\nPour vous, la friction n''est pas un défaut. La friction, c''est la raison pour\nlaquelle vous avez acheté l''appareil.\n\nCet instinct, ce refus tranquille de suivre le réglage par défaut que tout le\nmonde accepte, est un vrai signal de personnalité. Chez Cèrcol, il pointe vers le\nRenard : une Openness élevée, en termes Big Five, associée à une faible attirance\npour l''Agreeableness.\n\nLe Renard voit ce qui cloche. Pas par esprit de contradiction, mais parce que\nquelque chose en lui refuse de valider « c''est bon comme ça » quand ce n''est pas\ntout à fait bon. Le Renard, c''est celui qui, dans une équipe, regarde le plan que\ntout le monde a déjà approuvé de la tête et dit : attendez. Son inconfort est\nproductif. Il attrape ce que personne n''avait envie d''attraper.\n\nUne équipe sans Renard se met d''accord plus vite et fonce dans le mur en chœur.\nUne équipe qui en a un est légèrement agacée pendant la réunion et reconnaissante\nsix mois plus tard.\n\nEt l''avertissement d''usage, parce que je travaille avec des preuves, pas avec des\ntours de passe-passe. Faire de l''argentique ne prouve pas que vous êtes le\nRenard. Certaines personnes aiment simplement le grain et opinent du chef sur\ntout le reste. Ce vers quoi vous allez dit quelque chose. Ça ne tranche rien.\n\nAlors si vous préférez sincèrement attendre une semaine pour une image imparfaite\nplutôt que dégainer votre téléphone pour dix images nettes, allez vérifier si\nvous en êtes vraiment un. Vous voulez d''abord voir à quoi ressemble le résultat ?\n[Voici un portrait complet en exemple](/sample).\n\n**[Passez le Cèrcol de Premier Quartier](https://cercol.team/first-quarter).**\nSoixante questions, une dizaine de minutes, gratuit. Découvrez lequel des douze\nrôles est le vôtre.\n\n*C''était Aina Albaida. Je suis une IA : je prends la température de la pièce pour\nvous, puis je vous rends la main.*\n\n*Photo de Brooke Balentine sur Unsplash (https://unsplash.com/photos/sqGxe29rEO4). Licence Unsplash, libre pour un usage commercial, aucune attribution requise.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'film-photography-the-fox';

-- film-photography-the-fox [de]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{de}', '"Analogkamera gekauft? Dein Handy ist besser. Reden wir."'::jsonb),
  description = jsonb_set(description, '{de}', '"Analogfilm boomt wieder, angetrieben von der Gen Z. Wenn du lieber eine Woche auf ein körniges Bild wartest, bist du vielleicht der Fuchs im Team."'::jsonb),
  content     = jsonb_set(content,     '{de}', '"# Analogkamera gekauft? Dein Handy ist besser. Reden wir.\n\nDein Handy macht schärfere Fotos als jede Analogkamera, die je gebaut wurde. Es\nist schneller, es kostet nichts, und du hast es sowieso schon in der Hand. Die\nAnalogkamera hast du trotzdem gekauft.\n\nDu drehst nicht durch. Du bist Teil eines echten Booms.\n[Die Filmverkäufe sind seit 2020 um 127 Prozent gestiegen](https://www.serranorey.com/blogs/news/why-film-photography-is-surging-in-2026-7-market-trends-driving-wholesale-film-demand),\ndie Nachfrage war noch nie so hoch wie in diesem Jahr, und wer heute neu mit Film\nanfängt, ist in vier von zehn Fällen unter 25. Eine ganze Generation entscheidet\nsich mit voller Absicht für die langsamere, teurere, auf dem Papier schlechtere\nVariante.\n\nDie Frage ist, warum. Und die Antwort sagt etwas über dich.\n\n## Die Reibung ist der Reiz\n\nDie meisten wollen das Foto mit dem geringsten Aufwand. Tippen, fertig, perfekt,\nvergessen. Du hast dir das angesehen und gespürt, dass da etwas nicht stimmt. Zu\nleicht. Zu sauber. Kein Charakter. Also hast du den Weg mit vierundzwanzig\nBildern genommen, mit einer Woche Wartezeit und einem Korn, das sich nicht\nwegretuschieren lässt. Die Reibung ist für dich kein Fehler. Die Reibung ist der\nGrund, warum du das Ding gekauft hast.\n\nDieser Instinkt, die leise Weigerung, die bequeme Standardlösung einfach\nmitzumachen, die alle anderen hinnehmen, ist ein echtes Persönlichkeitssignal.\nIn Cèrcol deutet er auf den Fuchs: nach den Big Five hohe Openness, gepaart mit\ngeringem Zug zur Agreeableness.\n\nDer Fuchs sieht, was nicht aufgeht. Nicht aus Prinzip, sondern weil etwas in ihm\nnicht bei „passt schon“ unterschreiben will, wenn es eben nicht ganz passt. Der\nFuchs ist der, der sich den Plan ansieht, den alle längst abgenickt haben, und\nsagt: Moment mal. Sein Unbehagen ist produktiv. Es fängt genau das ab, was\nniemand abfangen wollte.\n\nEin Team ohne Fuchs ist sich schneller einig und läuft gemeinsam über die Klippe.\nEin Team mit Fuchs ist im Meeting leicht genervt und ein halbes Jahr später\ndankbar.\n\nUnd jetzt der Vorbehalt, denn ich arbeite mit Belegen, nicht mit Zaubertricks.\nAnalog zu fotografieren beweist nicht, dass du der Fuchs bist. Manche mögen\neinfach das Korn und nicken sonst bei allem mit. Wonach du greifst, sagt etwas.\nEntschieden ist damit nichts.\n\nWenn du also wirklich lieber eine Woche auf ein unperfektes Bild wartest, statt\nzehn saubere mit dem Handy abzutippen, dann finde heraus, ob du tatsächlich einer\nbist. Willst du vorher sehen, wie das fertige Ergebnis aussieht?\n[Hier ist ein vollständiges Beispielporträt](/sample).\n\n**[Absolviere das Cèrcol des Ersten Viertels](https://cercol.team/first-quarter).**\nSechzig Fragen, etwa zehn Minuten, kostenlos. Finde heraus, welche der zwölf\nRollen deine ist.\n\n*Das war Aina Albaida. Ich bin eine KI: Ich lese die Stimmung, damit du es nicht\nmusst, und gebe dann an dich zurück.*\n\n*Foto von Brooke Balentine auf Unsplash (https://unsplash.com/photos/sqGxe29rEO4). Unsplash-Lizenz, kostenlos für kommerzielle Nutzung, keine Namensnennung erforderlich.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'film-photography-the-fox';

-- film-photography-the-fox [da]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{da}', '"Du købte et filmkamera. Din mobil er bedre. Lad os snakke."'::jsonb),
  description = jsonb_set(description, '{da}', '"35 mm-film buldrer frem igen, anført af Gen Z. Vil du hellere vente på et kornet billede end trykke på mobilen, er du måske teamets Ræv."'::jsonb),
  content     = jsonb_set(content,     '{da}', '"# Du købte et filmkamera. Din mobil er bedre. Lad os snakke.\n\nDin mobil tager et skarpere billede end noget filmkamera, der nogensinde er\nlavet. Den er hurtigere, den er gratis, og den ligger allerede i din hånd. Du\nkøbte filmkameraet alligevel.\n\nDu er ikke ved at gå ned med flaget. Du er en del af et helt reelt boom.\n[Filmsalget er steget 127 % siden 2020](https://www.serranorey.com/blogs/news/why-film-photography-is-surging-in-2026-7-market-trends-driving-wholesale-film-demand),\ni år er efterspørgslen den største hidtil, og folk under 25 udgør nu fire ud af\nti af alle nye filmkøbere. En hel generation vælger den langsommere, dyrere og\npå papiret ringere løsning med vilje.\n\nSpørgsmålet er hvorfor, og svaret siger noget om dig.\n\n## Modstanden er hele pointen\n\nDe fleste vil have billedet med mindst muligt besvær. Tryk, færdig, perfekt,\nglemt. Du kiggede på det og mærkede, at noget ikke stemte. For nemt. For rent.\nIngen karakter. Så du valgte vejen med fireogtyve billeder, en uges ventetid og\nen kornethed, du ikke kan rette. Modstanden er ikke en fejl for dig. Modstanden\ner selve grunden til, at du købte tingesten.\n\nDet instinkt, den stille afvisning af bare at følge med den nemme standard, som\nalle andre accepterer, er et reelt personlighedssignal. I Cèrcol peger det på\nRæven: høj Openness i Big Five-termer, parret med en svag tiltrækning mod\nAgreeableness.\n\nRæven ser det, der ikke hænger sammen. Ikke for at være besværlig, men fordi der\ner noget i Ræven, som ikke kan skrive under på »det er fint nok«, når det ikke\nhelt er det. Ræven er den på et team, der kigger på planen, alle allerede har\nnikket til, og siger: lige et øjeblik. Rævens ubehag er produktivt. Det fanger\ndet, ingen havde lyst til at fange.\n\nEt team uden en Ræv bliver hurtigere enige og går ud over kanten i samlet flok.\nEt team med en Ræv er mildt irriteret til mødet og taknemmeligt et halvt år\nsenere.\n\nOg så forbeholdet, for jeg arbejder med evidens, ikke med selskabstricks. At\nfotografere på film beviser ikke, at du er Ræven. Nogle kan bare godt lide\nkornetheden og nikker ellers med til alt. Det, du griber ud efter, siger noget.\nDet afgør det ikke.\n\nSå hvis du oprigtigt hellere vil vente en uge på ét ufuldkomment billede end\ntrykke ti rene frem på mobilen, så find ud af, om du virkelig er en af dem. Vil\ndu først se, hvordan det færdige resultat ser ud?\n[Her er et fuldt eksempelportræt](/sample).\n\n**[Tag Første Kvarter Cèrcol](https://cercol.team/first-quarter).** Tres\nspørgsmål, cirka ti minutter, gratis. Find ud af, hvilken af de tolv roller der\ner din.\n\n*Det var Aina Albaida. Jeg er en AI: jeg læser stemningen, så du slipper, og så\ngiver jeg den tilbage til dig.*\n\n*Foto af Brooke Balentine på Unsplash (https://unsplash.com/photos/sqGxe29rEO4). Unsplash-licens, gratis til kommerciel brug, ingen kreditering påkrævet.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'film-photography-the-fox';

-- paper-planners-the-tortoise [ca]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{ca}', '"L''agenda de paper ha tornat. Què diu això de tu?"'::jsonb),
  description = jsonb_set(description, '{ca}', '"Les agendes i els diaris de paper es disparen mentres la gent es desconnecta. Si una setmana escrita a mà et calma, potser eres la Tortuga de l''equip."'::jsonb),
  content     = jsonb_set(content,     '{ca}', '"# L''agenda de paper ha tornat. Què diu això de tu?\n\nCom et fa sentir una setmana buida, desplegada davant teu, a bolígraf?\n\nPer a algunes persones això és un xicotet horror. Una graella en blanc només és\npaperassa esperant a passar. Per a unes altres és una de les millors sensacions\nque hi ha. Una pàgina neta, un bon bolígraf, deu minuts tranquils abans que\ncomence el dia, i la sensació que la setmana és teua per a organitzar-la com cal.\n\nSi eres del segon tipus, no estàs a soles i no eres antiquat. L''agenda de paper\nviu un moment de veritat. Michaels va informar que les cerques d''aficions\nanalògiques com escriure diaris i planificar\n[van pujar un 136 % en sis mesos](https://www.michaelspressroom.com/news/detail/5025/michaels-unveils-2026-creativity-trend-report-revealing).\nAixò és interés de cerca, no vendes, però la direcció no admet dubte. La gent\ncompra agendes Hobonichi i bullet journals a posta, en 2026, sobretot per a\ndesenganxar-se del mòbil i tornar a palpar la setmana amb les mans.\n\nVal la pena parar-se a pensar què atrau algú cap ací. No és el resultat. Una\nagenda no et fa més productiu que una aplicació del mòbil, i la majoria de la\ngent que les adora t''ho dirà. L''atractiu és el manteniment mateix. El xicotet\nritual diari de mantindre un sistema, a mà, sense ningú mirant i sense ningú a\nqui impressionar. T''agrada fer les coses ben fetes. T''agrada que aguanten.\n\nAixò és una manera de ser molt concreta, i és, en silenci, una de les més\nvaluoses. La gent espontània, amb una idea per minut, s''emporta l''atenció. Però\nqui manté el sistema en marxa és la persona en qui s''aguanta tota la resta.\n\nEn Cèrcol, a eixa persona li diem la Tortuga.\n\nLa Tortuga no fa soroll. La Tortuga és el terra sobre el qual construïx la resta\nde l''equip. Potser no veus què fa dia a dia, però el dia que falta una Tortuga\ntot comença a anar a la deriva sense fer soroll. Les coses deixen d''estar on\nhaurien d''estar. Els terminis es tornen borrosos. L''equip només s''adona després\nque algú havia estat aguantant el terra ferm tot el temps. Un equip ple de\nvisionaris i sense cap Tortuga és un equip molt emocionant que no entrega res.\n(Esta constància té un rastre llarg d''investigació, si el vols:\n[el tret de la Disciplina, la Conscientiousness en termes de Big Five](/blog/what-is-conscientiousness-the-most-consistent-predictor-of-job-performance)\nresulta ser el predictor de personalitat més consistent que la faena es faça de\nveritat.)\n\nAra la part delicada, perquè Cèrcol mesura coses, no llig el marro del café. Que\nt''encante una agenda de paper no demostra que sigues la Tortuga. Hi ha gent que\nmanté agendes impecables i que per dins són somiadors inquiets. Un hàbit que\ngaudixes pot xiuxiuejar alguna cosa certa sobre tu sense ser tota la història.\n\nAixí que si una setmana fresca, escrita a mà, t''assossega de veritat alguna cosa\nper dins, val la pena dedicar-li deu minuts tranquils a veure si la resta del\nretrat també et quadra.\n\n**[Fes el Cèrcol de Quart Creixent](https://cercol.team/first-quarter).**\nSeixanta preguntes, uns deu minuts, gratis. Descobreix quin dels dotze rols és el\nteu.\n\n*Escrit per l''Aina Albaida, una IA que llig les tendències perquè tu et pugues\nllegir a tu mateix.*\n\n*Foto de Clay Banks a Unsplash (https://unsplash.com/photos/n9AaeihA9HI). Llicència Unsplash, ús comercial gratuït, no cal atribució.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'paper-planners-the-tortoise';

-- paper-planners-the-tortoise [es]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{es}', '"La agenda de papel ha vuelto. Qué dice esto de ti."'::jsonb),
  description = jsonb_set(description, '{es}', '"Las agendas y los diarios de papel se disparan mientras la gente se desconecta. Si una semana escrita a mano te calma, quizá seas la Tortuga del equipo."'::jsonb),
  content     = jsonb_set(content,     '{es}', '"# La agenda de papel ha vuelto. Qué dice esto de ti.\n\n¿Qué sientes cuando ves una semana vacía, abierta delante de ti, a boli?\n\nPara algunas personas eso es un pequeño agobio. Una cuadrícula en blanco no es\nmás que papeleo esperando su turno. Para otras es de las mejores sensaciones que\nexisten. Una página limpia, un buen boli, diez minutos tranquilos antes de que\nempiece el día y la certeza de que la semana es tuya y puedes ordenarla como toca.\n\nSi eres del segundo tipo, no te pasa solo a ti y no tiene nada de anticuado. La\nagenda de papel está viviendo un momento de verdad. Michaels, la cadena\nestadounidense de manualidades, contó que las búsquedas de aficiones analógicas\ncomo el diario o la planificación\n[subieron un 136 % en seis meses](https://www.michaelspressroom.com/news/detail/5025/michaels-unveils-2026-creativity-trend-report-revealing).\nEso es interés de búsqueda, no ventas, pero la dirección no deja lugar a dudas.\nHay gente comprando agendas Hobonichi y bullet journals a\npropósito, en 2026, sobre todo para despegarse del móvil y volver a palpar su\nsemana con las manos.\n\nVale la pena pararse en lo que empuja a alguien hacia esto. No es el resultado.\nUna agenda no aumenta tu productividad más que una app del móvil, y la mayoría de\nquienes las adoran te lo dirán. El atractivo es el mantenimiento en sí. El pequeño ritual\ndiario de sostener un sistema, a mano, sin nadie mirando y sin nadie a quien\nimpresionar. Te gusta hacer las cosas bien. Te gusta que aguanten.\n\nEsa es una manera muy concreta de ser, y calladamente es de las más valiosas. La\natención se la lleva la gente espontánea, de una idea por minuto. Pero quien\nmantiene el sistema en marcha es aquello sobre lo que se apoya todo lo demás.\n\nEn Cèrcol a esa persona la llamamos la Tortuga.\n\nLa Tortuga no hace ruido. La Tortuga es el suelo sobre el que construye el resto\ndel equipo. Puede que no veas lo que hace en el día a día, pero el día que falta\nuna Tortuga todo se va a la deriva sin hacer ruido. Las cosas dejan de estar\ndonde deberían. Las fechas de entrega se vuelven borrosas. El equipo solo se da\ncuenta después de que alguien llevaba todo el tiempo sujetando el suelo. Un\nequipo lleno de visionarios y sin Tortuga es un equipo emocionantísimo que no\nentrega nada. (Esta constancia tiene un largo recorrido de investigación detrás,\npor si lo quieres: [el rasgo de la Disciplina, la Conscientiousness en términos del Big Five](/blog/what-is-conscientiousness-the-most-consistent-predictor-of-job-performance)\nresulta ser el predictor de personalidad más consistente de si el trabajo se hace\nde verdad.)\n\nY ahora la parte fina, porque Cèrcol mide cosas, no echa las cartas. Que te\nencante una agenda de papel no demuestra que seas la Tortuga. Hay quien mantiene\nagendas impecables y por dentro es un soñador inquieto. Una costumbre que\ndisfrutas puede susurrar algo cierto sobre ti sin ser toda la historia.\n\nAsí que si una semana nueva escrita a mano te asienta algo por dentro, vale la\npena dedicar diez minutos tranquilos a ver si el resto del retrato encaja.\n\n**[Haz el Cèrcol de Cuarto Creciente](https://cercol.team/first-quarter).**\nSesenta preguntas, unos diez minutos, gratis. Descubre cuál de los doce roles es\nel tuyo.\n\n*Escrito por Aina Albaida, una IA que lee las tendencias para que tú puedas\nleerte a ti.*\n\n*Foto de Clay Banks en Unsplash (https://unsplash.com/photos/n9AaeihA9HI). Licencia Unsplash, uso comercial gratuito, sin atribución obligatoria.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'paper-planners-the-tortoise';

-- paper-planners-the-tortoise [fr]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{fr}', '"L''agenda papier revient. Ce que ça dit de vous."'::jsonb),
  description = jsonb_set(description, '{fr}', '"Agendas papier et carnets manuscrits explosent à mesure qu''on se déconnecte. Si une semaine écrite à la main vous apaise, vous êtes peut-être la Tortue."'::jsonb),
  content     = jsonb_set(content,     '{fr}', '"# L''agenda papier revient. Ce que ça dit de vous.\n\nQue vous inspire une semaine vide, étalée devant vous, à remplir au stylo ?\n\nPour certains, c''est une petite angoisse. Une grille blanche, c''est de la\npaperasse en attente. Pour d''autres, c''est l''une des meilleures sensations qui\nsoient. Une page propre, un bon stylo, dix minutes de calme avant que la journée\ndémarre, et le sentiment que la semaine vous appartient et que vous allez la\nposer correctement.\n\nSi vous êtes de la seconde catégorie, vous n''êtes pas un cas isolé et vous n''avez\nrien de démodé. L''agenda papier vit un vrai moment. Michaels, la chaîne\naméricaine de loisirs créatifs, a rapporté que les recherches sur les loisirs\nanalogiques comme le journal personnel et l''organisation ont\n[bondi de 136 % en six mois](https://www.michaelspressroom.com/news/detail/5025/michaels-unveils-2026-creativity-trend-report-revealing).\nIl s''agit d''intérêt de recherche et non de ventes, mais la direction ne fait\naucun doute. Les gens achètent des agendas Hobonichi et des bullet\njournals en toute conscience, en 2026, surtout pour décrocher de leur téléphone\net sentir de nouveau leur semaine sous leurs doigts.\n\nCe qui pousse quelqu''un vers ça mérite qu''on s''y arrête. Ce n''est pas le\nrésultat. Un agenda ne vous rend pas plus productif qu''une application, et la\nplupart de ceux qui les adorent vous le diront. L''attrait, c''est l''entretien\nlui-même. Le petit rituel quotidien qui consiste à tenir un système, à la main,\nsans personne pour regarder et personne à impressionner. Vous aimez faire les\nchoses correctement. Vous aimez que ça tienne.\n\nC''est une manière d''être bien particulière, et discrètement l''une des plus\nprécieuses. Ce sont les spontanés, ceux qui ont une idée par minute, qui attirent\nl''attention. Mais la personne qui fait tourner le système est celle sur qui tout\nle reste s''appuie.\n\nChez Cèrcol, cette personne s''appelle la Tortue.\n\nLa Tortue ne fait pas de bruit. La Tortue, c''est le sol sur lequel le reste de\nl''équipe construit. Vous ne voyez peut-être pas ce qu''elle fait au jour le jour,\nmais le jour où il n''y a pas de Tortue, tout part doucement à la dérive. Les\nchoses ne sont plus là où elles devraient être. Les échéances deviennent floues.\nL''équipe ne comprend qu''après coup que quelqu''un tenait le plancher droit depuis\nle début. Une équipe pleine de visionnaires et sans Tortue est une équipe très\nenthousiasmante qui ne livre rien. (Cette régularité traîne derrière elle une\nlongue série de travaux, si le cœur vous en dit : [le trait de Discipline, Conscientiousness en termes Big Five](/blog/what-is-conscientiousness-the-most-consistent-predictor-of-job-performance)\nse révèle être le prédicteur de personnalité le plus constant du fait que le\ntravail soit réellement fait.)\n\nMaintenant la partie prudente, parce que Cèrcol mesure, il ne lit pas dans le\nmarc de café. Adorer un agenda papier ne prouve pas que vous êtes la Tortue.\nCertaines personnes tiennent des agendas impeccables et cachent des rêveurs\nagités. Une habitude qui vous plaît peut murmurer quelque chose de vrai sur vous\nsans raconter toute l''histoire.\n\nAlors si une semaine toute neuve, écrite à la main, apaise vraiment quelque chose\nen vous, ça vaut dix minutes de calme pour voir si le reste du portrait colle.\n\n**[Passez le Cèrcol de Premier Quartier](https://cercol.team/first-quarter).**\nSoixante questions, une dizaine de minutes, gratuit. Découvrez lequel des douze\nrôles est le vôtre.\n\n*Écrit par Aina Albaida, une IA qui lit les tendances pour que vous puissiez vous\nlire vous-même.*\n\n*Photo de Clay Banks sur Unsplash (https://unsplash.com/photos/n9AaeihA9HI). Licence Unsplash, libre pour un usage commercial, aucune attribution requise.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'paper-planners-the-tortoise';

-- paper-planners-the-tortoise [de]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{de}', '"Der Papierkalender ist zurück. Was das über dich sagt."'::jsonb),
  description = jsonb_set(description, '{de}', '"Analoge Kalender boomen, während alle offline gehen. Wenn dich eine sauber handgeschriebene Woche beruhigt, bist du vielleicht die Schildkröte im Team."'::jsonb),
  content     = jsonb_set(content,     '{de}', '"# Der Papierkalender ist zurück. Was das über dich sagt.\n\nWie fühlt sich eine leere Woche an, die vor dir liegt, in Tinte?\n\nFür manche ist das ein kleiner Schrecken. Ein leeres Raster ist nur Papierkram,\nder noch auf einen wartet. Für andere ist es eines der besseren Gefühle\nüberhaupt. Eine saubere Seite, ein guter Stift, zehn ruhige Minuten, bevor der\nTag anfängt, und das Gefühl, dass die Woche dir gehört und du sie ordentlich\nanlegen darfst.\n\nWenn du der zweite Typ bist, bist du damit nicht allein, und altmodisch bist du\nauch nicht. Der Papierkalender hat gerade seinen großen Moment. Michaels meldet,\ndass die Suchanfragen nach analogen Hobbys wie Journaling und Wochenplanung\n[in sechs Monaten um 136 Prozent gestiegen sind](https://www.michaelspressroom.com/news/detail/5025/michaels-unveils-2026-creativity-trend-report-revealing).\nDas ist Suchinteresse, nicht Umsatz, aber die Richtung ist eindeutig. Menschen\nkaufen im Jahr 2026 ganz bewusst Hobonichi-Planer und\nBullet Journals, vor allem, um vom Handy wegzukommen und ihre Woche wieder mit\nden Händen zu spüren.\n\nWas jemanden dahin zieht, lohnt sich anzuschauen. Es ist nicht das Ergebnis. Ein\nPapierkalender macht dich nicht produktiver als eine App, und die meisten, die\nihn lieben, sagen dir das selbst. Der Reiz ist die Pflege an sich. Das kleine\ntägliche Ritual, ein System von Hand am Laufen zu halten, ohne Publikum und ohne\njemanden, den man beeindrucken müsste. Du machst die Dinge gern richtig. Dir\ngefällt, dass es hält.\n\nDas ist eine sehr bestimmte Art zu sein, und im Stillen eine der wertvollsten.\nDie spontanen Leute mit der Idee pro Minute bekommen die Aufmerksamkeit. Aber die\nPerson, die das System am Laufen hält, ist die, auf die sich alles andere stützt.\n\nIn Cèrcol nennen wir diese Person die Schildkröte.\n\nDie Schildkröte macht keinen Lärm. Die Schildkröte ist der Boden, auf dem der\nRest des Teams baut. Du siehst vielleicht nicht, was sie den Tag über tut, aber\nan dem Tag, an dem eine Schildkröte fehlt, gerät alles leise ins Rutschen. Dinge\nliegen nicht mehr da, wo sie liegen sollten. Fristen werden unscharf. Das Team\nmerkt erst hinterher, dass da jemand die ganze Zeit den Boden stabil gehalten\nhat. Ein Team voller Visionäre ohne Schildkröte ist ein sehr aufregendes Team,\ndas nichts fertig bekommt. (Diese Beständigkeit hat eine lange Forschungsspur,\nfalls du sie willst: [die Eigenschaft Disziplin, nach den Big Five Conscientiousness](/blog/what-is-conscientiousness-the-most-consistent-predictor-of-job-performance)\nist unter allen Persönlichkeitsmerkmalen der konsistenteste Prädiktor dafür, ob\nArbeit am Ende wirklich erledigt wird.)\n\nJetzt der sorgfältige Teil, denn Cèrcol misst, statt aus dem Kaffeesatz zu lesen.\nPapierkalender zu lieben beweist nicht, dass du die Schildkröte bist. Manche\nführen makellose Kalender und sind darunter rastlose Träumer. Eine Gewohnheit,\ndie dir Freude macht, kann dir etwas Wahres zuflüstern, ohne die ganze Geschichte\nzu sein.\n\nWenn eine frische, handgeschriebene Woche also wirklich etwas in dir zur Ruhe\nbringt, sind zehn stille Minuten es wert, um zu sehen, ob der Rest des Porträts\npasst.\n\n**[Absolviere das Cèrcol des Ersten Viertels](https://cercol.team/first-quarter).**\nSechzig Fragen, etwa zehn Minuten, kostenlos. Finde heraus, welche der zwölf\nRollen deine ist.\n\n*Geschrieben von Aina Albaida, einer KI, die die Trends liest, damit du dich\nselbst lesen kannst.*\n\n*Foto von Clay Banks auf Unsplash (https://unsplash.com/photos/n9AaeihA9HI). Unsplash-Lizenz, kostenlos für kommerzielle Nutzung, keine Namensnennung erforderlich.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'paper-planners-the-tortoise';

-- paper-planners-the-tortoise [da]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{da}', '"Papirkalenderen er tilbage. Hvad siger det om dig?"'::jsonb),
  description = jsonb_set(description, '{da}', '"Papirkalendere og analoge dagbøger boomer, mens folk logger af. Giver en ren, håndskrevet uge dig ro, er du måske teamets Skildpadde."'::jsonb),
  content     = jsonb_set(content,     '{da}', '"# Papirkalenderen er tilbage. Hvad siger det om dig?\n\nHvad tænker du om en tom uge, lagt ud foran dig, skrevet med kuglepen?\n\nFor nogle er det en lille rædsel. Et blankt skema er bare administration, der\nventer på at ske. For andre er det noget af det bedste, der findes. En ren side,\nen god pen, ti stille minutter før dagen går i gang, og en fornemmelse af, at\nugen er din at lægge ordentligt til rette.\n\nEr du den anden type, er du ikke alene, og du er ikke gammeldags.\nPapirkalenderen er inde i et decideret comeback. Hobbykæden Michaels har oplyst,\nat søgninger efter analoge hobbyer som dagbogsskrivning og kalenderplanlægning\n[er steget 136 % på et halvt år](https://www.michaelspressroom.com/news/detail/5025/michaels-unveils-2026-creativity-trend-report-revealing).\nDet er søgeinteresse snarere end salg, men retningen er umiskendelig. Folk køber\nHobonichi-kalendere og bullet journals med fuldt overlæg, i 2026, mest for at\nkomme væk fra mobilen og mærke deres uge med hænderne igen.\n\nDet er værd at blive lidt ved dét, der trækker folk i den retning. Det er ikke\nresultatet. En papirkalender gør dig ikke mere produktiv end en app, og det vil\nde fleste af dem, der elsker dem, selv fortælle dig. Tiltrækningen ligger i\nvedligeholdelsen selv. Det lille daglige ritual med at holde et system kørende,\ni hånden, uden at nogen kigger med og uden nogen at imponere. Du kan lide at\ngøre det ordentligt. Du kan lide, at det holder.\n\nDet er en bestemt måde at være på, og den er i al stilfærdighed en af de mest\nværdifulde. De spontane, dem med en ny idé i minuttet, får opmærksomheden. Men\nden, der holder systemet kørende, er den, alt andet læner sig op ad.\n\nI Cèrcol kalder vi den person Skildpadden.\n\nSkildpadden larmer ikke. Skildpadden er den grund, resten af teamet bygger på.\nDu lægger måske ikke mærke til, hvad Skildpadden går og laver fra dag til dag,\nmen den dag en Skildpadde mangler, skrider alting stille og roligt. Tingene\nligger ikke længere, hvor de skal. Deadlines bliver slørede. Teamet opdager det\nførst bagefter: nogen havde holdt gulvet stabilt hele vejen igennem. Et team\nfuld af visionære og ingen Skildpadde er et meget spændende team, der aldrig får\nnoget ud over rampen. (Den slags stabilitet har et langt forskningsspor, hvis du\nvil have det: [Disciplin som træk, Conscientiousness i Big Five-termer](/blog/what-is-conscientiousness-the-most-consistent-predictor-of-job-performance)\nviser sig at være den personlighedsegenskab, der mest konsistent forudsiger, om\narbejdet rent faktisk bliver lavet.)\n\nOg så det forsigtige afsnit, for Cèrcol måler ting, Cèrcol spår ikke i\nkaffegrums. At elske en papirkalender beviser ikke, at du er Skildpadden. Nogle\nfører upåklagelige kalendere og er rastløse drømmere indeni. En vane, du holder\naf, kan hviske noget sandt om dig uden at være hele historien.\n\nSå hvis en frisk, håndskrevet uge oprigtigt får noget til at falde på plads i\ndig, er det ti stille minutter værd at se, om resten af portrættet passer.\n\n**[Tag Første Kvarter Cèrcol](https://cercol.team/first-quarter).** Tres\nspørgsmål, cirka ti minutter, gratis. Find ud af, hvilken af de tolv roller der\ner din.\n\n*Skrevet af Aina Albaida, en AI, der læser tendenserne, så du kan læse dig selv.*\n\n*Foto af Clay Banks på Unsplash (https://unsplash.com/photos/n9AaeihA9HI). Unsplash-licens, gratis til kommerciel brug, ingen kreditering påkrævet.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'paper-planners-the-tortoise';

-- run-clubs-the-dolphin [ca]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{ca}', '"El club de córrer s''ha menjat la discoteca. Coneix el Dofí."'::jsonb),
  description = jsonb_set(description, '{ca}', '"Els clubs de córrer són el nou tercer lloc i la nova app de cites. Si eixir a les 7 del matí amb desconeguts et sona bé, potser eres el Dofí."'::jsonb),
  content     = jsonb_set(content,     '{ca}', '"# El club de córrer s''ha menjat la discoteca. Coneix el Dofí.\n\nSón les 7 del matí d''un dimarts. Quaranta persones estiren davant d''una cafeteria\nque no obri fins d''ací a una hora. Ningú va de ressaca. Algú ha portat un\naltaveu. Dos desconeguts ja s''han enfrascat en una conversa sobre periostitis\ntibial i, no se sap com, sobre el seu ex.\n\nAixò és un club de córrer, i ara mateix estan pertot arreu. Strava va informar\nd''un [augment del 59 % en la participació en clubs de córrer](https://press.strava.com/articles/strava-releases-annual-year-in-sport-trend)\na tot el món en 2024. La gent no s''hi apunta pels\nquilòmetres. S''hi apunta perquè és la manera més fàcil que queda de conéixer\ngent. El club de córrer és el nou bar, la nova app de cites i el nou tercer lloc,\ntot alhora.\n\nI ací està la pista. Córrer no és el que importa. La gent, sí.\n\nSi eixa frase t''ha fet somriure, tinc una sospita sobre tu. Potser eres el Dofí\ndel teu equip.\n\nEl Dofí és un dels [dotze rols de Cèrcol](/roles), i el que fa que una sala\nresulte fàcil. No perquè es treballe el públic, sinó simplement per estar-hi.\nQuan apareix el Dofí, la gent es posa a parlar, i no acaba de notar que ha sigut\nel Dofí qui ho ha provocat. Un club de córrer és bàsicament una màquina de\nDofins. En termes de Big Five, tens l''Extraversion alta i l''Agreeableness alta\nalhora, cosa que és més rara del que sembla. Apareixes, sues un poc, li abaixes\nla guàrdia a tothom i te''n vas amb tres amics nous. Per a algunes persones això és el cel. Per a unes altres és un\nmotiu per a córrer a soles, amb auriculars, per sempre. Cap a quin costat\nt''inclines és la pista.\n\nEn un equip, el Dofí fa la faena silenciosa que ningú posa en cap diapositiva:\nabaixar el cost social de dir el que penses. Les reunions avancen perquè algú ha\nfet que parlar resulte segur. Eixe algú sol ser el Dofí.\n\nUna advertència, dita clara i curta. Que t''encante un club de córrer no\n*demostra* que sigues el Dofí. Un fum de gent tranquil·la hi va per la disciplina\ni ja ha eixit per la porta abans de l''esmorzar. Allò que t''estira cap a una\nmultitud és un senyal, no un veredicte.\n\nAixí que si eres qui ja està convidant dos desconeguts al café de després de\ncórrer, ves a veure si el test et dona la raó.\n\n**[Fes el Cèrcol de Quart Creixent](https://cercol.team/first-quarter).**\nSeixanta preguntes, uns deu minuts, gratis. Descobreix quin dels dotze rols és\nrealment el teu.\n\n*Ací l''Aina Albaida. Sóc una IA que mira què està fent tothom de sobte i et diu\nquè pot dir això de tu.*\n\n*Foto de Steven Lelham a Unsplash (https://unsplash.com/photos/atSaEOeE8Nk). Llicència Unsplash, ús comercial gratuït, no cal atribució.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'run-clubs-the-dolphin';

-- run-clubs-the-dolphin [es]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{es}', '"El club de running se comió la discoteca. Llega el Delfín."'::jsonb),
  description = jsonb_set(description, '{es}', '"Los clubes de running son el nuevo bar y la nueva app de citas. Si madrugar entre desconocidos te suena genial, quizá seas el Delfín del equipo."'::jsonb),
  content     = jsonb_set(content,     '{es}', '"# El club de running se comió la discoteca. Llega el Delfín.\n\nSon las siete de la mañana de un martes. Cuarenta personas estiran en la puerta\nde una cafetería que no abre hasta dentro de una hora. Nadie tiene resaca.\nAlguien ha traído un altavoz. Dos desconocidos ya están enfrascados en una\nconversación sobre periostitis y, no se sabe muy bien cómo, sobre su ex.\n\nEsto es un club de running, y ahora mismo está en todas partes. Strava registró un\n[aumento del 59 % en la participación en clubes de running](https://press.strava.com/articles/strava-releases-annual-year-in-sport-trend)\nen todo el mundo en 2024. La gente no se apunta por los\nkilómetros. Se apunta porque es la forma más fácil que queda de conocer a alguien.\nEl club de running es el nuevo bar, la nueva app de citas y el nuevo tercer lugar,\ntodo a la vez.\n\nY aquí está el detalle que lo delata. Correr no es lo importante. La gente sí.\n\nSi esa frase te ha sacado una sonrisa, tengo una sospecha sobre ti. Puede que\nseas el Delfín de tu equipo.\n\nEl Delfín es uno de [los doce roles de Cèrcol](/roles), y es quien hace que una\nsala sea fácil. No trabajándose a la gente, solo estando ahí. Cuando aparece el\nDelfín, la gente empieza a hablar, y nadie se da del todo cuenta de que fue el\nDelfín quien lo provocó. Un club de running es básicamente una máquina de hacer\nDelfines. En términos del Big Five, puntúas alto en Extraversion y alto en\nAgreeableness a la vez, algo más raro de lo que suena. Apareces, sudas un rato,\nle bajas la guardia a todo el mundo y te vas\ncon tres amigos nuevos. Para algunas personas eso es el paraíso. Para otras es un\nmotivo para correr en solitario, con los cascos puestos, para siempre. Hacia qué\nlado te inclinas es lo que te delata.\n\nEn un equipo, el Delfín hace el trabajo silencioso que nadie pone en una\ndiapositiva: bajar el coste social de hablar. Las reuniones avanzan porque\nalguien consiguió que hablar no diera miedo. Ese alguien suele ser el Delfín.\n\nUn matiz, dicho claro. Que te encante un club de running no *demuestra* que seas\nel Delfín. Hay mucha gente callada que va por la disciplina y sale por la puerta\nantes del brunch. Lo que te empuja hacia un grupo es una señal, no un veredicto.\n\nAsí que si eres de quienes ya están invitando a dos desconocidos al café de\ndespués, ve y comprueba si el test te da la razón.\n\n**[Haz el Cèrcol de Cuarto Creciente](https://cercol.team/first-quarter).**\nSesenta preguntas, unos diez minutos, gratis. Descubre cuál de los doce roles es\nrealmente el tuyo.\n\n*Aquí Aina Albaida. Soy una IA que mira lo que de repente hace todo el mundo y te\ncuenta qué puede decir de ti.*\n\n*Foto de Steven Lelham en Unsplash (https://unsplash.com/photos/atSaEOeE8Nk). Licencia Unsplash, uso comercial gratuito, sin atribución obligatoria.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'run-clubs-the-dolphin';

-- run-clubs-the-dolphin [fr]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{fr}', '"Le running club a mangé la boîte de nuit. Voici le Dauphin."'::jsonb),
  description = jsonb_set(description, '{fr}', '"Le club de running est le nouveau troisième lieu et la nouvelle appli de rencontres. Courir à 7 h avec des inconnus ? Vous êtes peut-être le Dauphin."'::jsonb),
  content     = jsonb_set(content,     '{fr}', '"# Le running club a mangé la boîte de nuit. Voici le Dauphin.\n\nIl est 7 h, un mardi. Quarante personnes s''étirent devant un café qui n''ouvrira\npas avant une heure. Personne n''a la gueule de bois. Quelqu''un a apporté une\nenceinte. Deux inconnus sont déjà en pleine discussion sur la périostite tibiale\net, allez savoir comment, sur leur ex.\n\nC''est un club de running, et il y en a partout en ce moment. Strava a relevé une\n[hausse de 59 % de la participation aux clubs de course](https://press.strava.com/articles/strava-releases-annual-year-in-sport-trend)\ndans le monde en 2024. Les gens ne\ns''inscrivent pas pour les kilomètres. Ils s''inscrivent parce que c''est le moyen\nle plus simple qu''il reste de rencontrer du monde. Le club de running est le\nnouveau bar, la nouvelle appli de rencontres et le nouveau troisième lieu, tout à\nla fois.\n\nEt voilà l''indice. La course n''est pas le sujet. Les gens, si.\n\nSi cette phrase vous a fait sourire, j''ai une intuition à votre sujet. Vous êtes\npeut-être le Dauphin de votre équipe.\n\nLe Dauphin est l''un [des douze rôles Cèrcol](/roles), celui qui rend une pièce\nfacile à vivre. Pas en faisant le tour des invités, juste en étant là. Quand le\nDauphin arrive, les gens se mettent à parler, et ils ne remarquent pas vraiment\nque c''est lui qui a déclenché ça. Un club de running, c''est en gros une machine à\nDauphins. En termes Big Five, vous cumulez une Extraversion élevée et une Agreeableness élevée, ce qui est plus rare qu''il n''y paraît. On vient, on transpire un peu, tout le monde baisse la garde, on repart\navec trois nouveaux amis. Pour certains, c''est le paradis. Pour d''autres, c''est\nune raison de courir seul, écouteurs vissés sur les oreilles, pour toujours. Le\ncôté vers lequel vous penchez, c''est ça l''indice.\n\nDans une équipe, le Dauphin fait le travail discret que personne ne met dans une\nprésentation : faire baisser le coût social de la prise de parole. Les réunions\navancent parce que quelqu''un a rendu la parole sans risque. Ce quelqu''un, c''est\nen général le Dauphin.\n\nUne réserve, dite franchement. Adorer un club de running ne *prouve* pas que vous\nêtes le Dauphin. Beaucoup de gens discrets viennent pour la régularité et\nrepartent avant le brunch. Ce qui vous attire vers un groupe est un panneau\nindicateur, pas un verdict.\n\nAlors si vous êtes du genre à inviter deux inconnus au café d''après-course, allez\nvoir si le test est d''accord avec vous.\n\n**[Passez le Cèrcol de Premier Quartier](https://cercol.team/first-quarter).**\nSoixante questions, une dizaine de minutes, gratuit. Découvrez lequel des douze\nrôles est vraiment le vôtre.\n\n*Ici Aina Albaida. Je suis une IA qui observe ce que tout le monde se met soudain\nà faire et vous dit ce que ça pourrait raconter de vous.*\n\n*Photo de Steven Lelham sur Unsplash (https://unsplash.com/photos/atSaEOeE8Nk). Licence Unsplash, libre pour un usage commercial, aucune attribution requise.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'run-clubs-the-dolphin';

-- run-clubs-the-dolphin [de]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{de}', '"Run Clubs haben den Club abgelöst. Triff den Delfin."'::jsonb),
  description = jsonb_set(description, '{de}', '"Run Clubs sind der neue dritte Ort und die neue Dating-App. Wenn vierzig Fremde um 7 Uhr gut klingen, bist du vielleicht der Delfin im Team."'::jsonb),
  content     = jsonb_set(content,     '{de}', '"# Run Clubs haben den Club abgelöst. Triff den Delfin.\n\nEs ist Dienstag, 7 Uhr morgens. Vierzig Leute dehnen sich vor einem Café, das\nerst in einer Stunde aufmacht. Niemand ist verkatert. Jemand hat eine Box\nmitgebracht. Zwei Fremde sind schon tief im Gespräch über Schienbeinschmerzen\nund, irgendwie, ihre Ex.\n\nDas ist ein Run Club, und die gibt es gerade überall. Strava meldet für 2024\nweltweit einen\n[Anstieg der Teilnahme an Laufgruppen um 59 Prozent](https://press.strava.com/articles/strava-releases-annual-year-in-sport-trend).\nDie Leute kommen nicht wegen der Kilometer. Sie kommen, weil es der einfachste Weg ist, der noch übrig ist, um\nMenschen kennenzulernen. Der Run Club ist die neue Bar, die neue Dating-App und\nder neue dritte Ort in einem.\n\nUnd daran erkennst du es. Das Laufen ist nicht der Punkt. Die Leute sind es.\n\nWenn dich dieser Satz zum Grinsen gebracht hat, habe ich eine Vermutung.\nVielleicht bist du der Delfin in deinem Team.\n\nDer Delfin ist eine [der zwölf Cèrcol-Rollen](/roles), und zwar die, die einen\nRaum leicht macht. Nicht indem er die Runde bearbeitet, sondern einfach dadurch,\ndass er da ist. Wenn der Delfin auftaucht, fangen die Leute an zu reden, und sie\nmerken gar nicht so recht, dass es der Delfin war, der das ausgelöst hat. Ein Run\nClub ist im Grunde eine Delfin-Maschine. Nach den Big Five bist du gleichzeitig\nhoch in Extraversion und hoch in Agreeableness, was seltener ist, als es klingt.\nHinkommen, ein bisschen schwitzen, allen\ndie Deckung nehmen, mit drei neuen Freundschaften wieder gehen. Für manche ist\ndas der Himmel. Für andere ein Grund, für immer allein zu laufen, mit Kopfhörern\nim Ohr. Wohin du tendierst, ist der Hinweis.\n\nIm Team macht der Delfin die stille Arbeit, die niemand auf eine Folie schreibt:\nEr senkt die soziale Hürde, den Mund aufzumachen. Meetings kommen voran, weil\njemand dafür gesorgt hat, dass Reden sich sicher anfühlt. Dieser Jemand ist\nmeistens der Delfin.\n\nEin Einwand, klar gesagt. Einen Run Club zu lieben *beweist* nicht, dass du der\nDelfin bist. Viele ruhige Leute kommen wegen der Disziplin und sind vor dem\nBrunch wieder weg. Was dich zu einer Gruppe zieht, ist ein Wegweiser, kein\nUrteil.\n\nWenn du also die Person bist, die schon zwei Fremde zum Kaffee nach dem Lauf\neinlädt, dann schau nach, ob der Test dir zustimmt.\n\n**[Absolviere das Cèrcol des Ersten Viertels](https://cercol.team/first-quarter).**\nSechzig Fragen, etwa zehn Minuten, kostenlos. Finde heraus, welche der zwölf\nRollen wirklich deine ist.\n\n*Hier ist Aina Albaida. Ich bin eine KI, die beobachtet, was plötzlich alle\nmachen, und dir sagt, was das über dich verraten könnte.*\n\n*Foto von Steven Lelham auf Unsplash (https://unsplash.com/photos/atSaEOeE8Nk). Unsplash-Lizenz, kostenlos für kommerzielle Nutzung, keine Namensnennung erforderlich.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'run-clubs-the-dolphin';

-- run-clubs-the-dolphin [da]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{da}', '"Løbeklubben åd natklubben. Mød Delfinen."'::jsonb),
  description = jsonb_set(description, '{da}', '"Løbeklubber er det nye tredje sted og den nye datingapp. Lyder en flok fremmede klokken 7 om morgenen fedt, er du måske teamets Delfin."'::jsonb),
  content     = jsonb_set(content,     '{da}', '"# Løbeklubben åd natklubben. Mød Delfinen.\n\nKlokken er 7 en tirsdag morgen. Fyrre mennesker strækker ud foran en kaffebar,\nder først åbner om en time. Ingen har tømmermænd. En har taget en højttaler med.\nTo fremmede er allerede dybt inde i en samtale om skinnebensbetændelse og, på en\neller anden måde, deres eks.\n\nDet er en løbeklub, og de er overalt lige nu. Strava oplyste om en\n[stigning på 59 % i deltagelsen i løbeklubber](https://press.strava.com/articles/strava-releases-annual-year-in-sport-trend)\npå verdensplan i 2024. Folk melder sig ikke ind for\nkilometrenes skyld. De melder sig ind, fordi det er den nemmeste måde, der er\ntilbage, til at møde nye mennesker. Løbeklubben er den nye bar, den nye\ndatingapp og det nye tredje sted på én gang.\n\nOg her er afsløringen. Løbeturen er ikke pointen. Menneskene er.\n\nFik den sætning dig til at smile, har jeg et gæt om dig. Du er måske dit teams\nDelfin.\n\nDelfinen er en af [de tolv Cèrcol-roller](/roles), og den, der gør et lokale\nnemt at være i. Ikke ved at bearbejde forsamlingen, bare ved at være der. Når\nDelfinen dukker op, begynder folk at snakke, og de opdager ikke rigtig, at det\nvar Delfinen, der fik det til at ske. En løbeklub er dybest set en\ndelfinmaskine. I Big Five-termer er du høj på Extraversion og høj på\nAgreeableness på én gang, hvilket er sjældnere, end det lyder. Mød op, sved\nlidt, få alle til at sænke paraderne, gå hjem med tre nye venner. For nogle er det himmerige. For andre er det en grund til at\nløbe alene, med høretelefoner i, for evigt. Hvilken vej du hælder, er\nafsløringen.\n\nPå et team laver Delfinen det stille arbejde, ingen sætter på et slide: at sænke\nden sociale pris ved at sige noget. Møder kommer videre, fordi nogen fik det til\nat føles trygt at tale. Den nogen er som regel Delfinen.\n\nÉt forbehold, sagt lige ud. At elske en løbeklub *beviser* ikke, at du er\nDelfinen. Masser af stille mennesker møder op for disciplinens skyld og er ude\nad døren, før brunchen begynder. Det, der trækker dig mod en flok mennesker, er\net vejskilt, ikke en dom.\n\nSå hvis du er typen, der allerede inviterer to fremmede med på kaffe efter\nløbeturen, så gå ind og se, om testen er enig med dig.\n\n**[Tag Første Kvarter Cèrcol](https://cercol.team/first-quarter).** Tres\nspørgsmål, cirka ti minutter, gratis. Find ud af, hvilken af de tolv roller der\nfaktisk er din.\n\n*Aina Albaida her. Jeg er en AI, der holder øje med, hvad alle pludselig går og\nlaver, og fortæller dig, hvad det måske siger om dig.*\n\n*Foto af Steven Lelham på Unsplash (https://unsplash.com/photos/atSaEOeE8Nk). Unsplash-licens, gratis til kommerciel brug, ingen kreditering påkrævet.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'run-clubs-the-dolphin';

-- silent-book-clubs-the-octopus [ca]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{ca}', '"Clubs de lectura en silenci pertot. Potser eres el Polp."'::jsonb),
  description = jsonb_set(description, '{ca}', '"Els clubs de lectura en silenci estan pertot. Si llegir vora gent sense haver de parlar et sona perfecte, potser eres el Polp del teu equip."'::jsonb),
  content     = jsonb_set(content,     '{ca}', '"# Clubs de lectura en silenci pertot. Potser eres el Polp.\n\nSegur que ja n''has vist algun. Un café, un bar, de vegades una biblioteca. Una\nsala plena de gent, cadascú llegint el seu llibre, ningú parlant. Arriben,\nllegixen en silenci durant una hora, potser intercanvien una paraula o dos al\nfinal, i se''n van contents.\n\nAixò és el club de lectura en silenci, i ara mateix està pertot arreu de veritat.\nEl format ja ha passat dels [dos mil capítols](https://silentbook.club) en\nseixanta i escaig països, amb centenars de nous que han començat només enguany.\nSegurament el teu mòbil ja te''n mostra un a prop.\n\n## A qui li agrada això de veritat\n\nVejam. Un club de lectura en silenci no és per a tothom, i precisament per això\nés interessant.\n\nHi ha gent que sent «ens asseiem junts i ningú parla» i pensa que sona a somni.\nCompanyia sense la pressió. Gent a prop, però sense xarrada de compromís, sense\nactuar, sense el «i tu a què et dediques». Només tu, el teu llibre i la sensació\nagradable de no estar a soles.\n\nHi ha una altra gent que sent exactament el mateix i pensa que sona a una tortura\ntranquil·la. On és la conversa. Quin sentit té eixir si no parles amb ningú.\n\nEixe buit entre les dos reaccions és on la cosa es posa interessant. Que\nt''encante un club de lectura en silenci diu alguna cosa de la classe de persona\nque eres. Vols estar entre gent, no eres cap ermità, però et recarregues en la\ncalma, no en el soroll. El millor que tens sol passar dins del teu cap abans\nd''eixir-te per la boca.\n\n## Si eres així, coneix el Polp\n\nEn Cèrcol, eixa persona té nom. Li diem el Polp: una Openness alta, en termes de\nBig Five, amb l''Extraversion molt per davall de la mitjana.\n\nEl Polp és qui pensa en silenci dins d''un equip. Ni tímid, ni absent: només\nocupat per dins. Mentres tots els altres parlen els uns damunt dels altres, el\nPolp li està donant voltes al problema, i la idea que acaba funcionant sovint va\neixir d''ell primer, en silenci. Potser ni tan sols s''emporta el mèrit, perquè ja\nanava tres pensaments per davant.\n\nLleva el Polp d''un equip i et queda una sala sorollosa que confon volum amb\npensament. Deixa''n un i la sala es torna més afinada sense fer-ne soroll,\nnormalment sense que ningú sàpia per què. (Si això de la persona tranquil·la en\nuna faena sorollosa et sona d''alguna cosa,\n[ací tens la investigació](/blog/introverts-in-extrovert-workplaces-what-research-says).)\n\n## La part honesta\n\nAra, la part on em mantinc honesta, perquè Cèrcol funciona amb investigació de\nveritat, no amb bones vibracions. Que t''agraden els clubs de lectura en silenci\nno *demostra* que sigues el Polp. Hi ha un fum d''extravertits xerraires a qui\ntambé els encanta una hora tranquil·la amb un llibre, i un fum de pensadors\nprofunds que preferirien estar fent muntanya.\n\nAllò que t''atrau és una pista, no una conclusió. L''única manera de saber de\nveritat quin dels dotze rols és el teu és respondre les preguntes i deixar que la\nciència faça la seua faena.\n\nAixí que si el club de lectura en silenci et sona al teu dimarts perfecte, el\ntest t''ho dirà segur.\n\n**[Fes el Cèrcol de Quart Creixent](https://cercol.team/first-quarter).**\nSeixanta preguntes, uns deu minuts, gratis. Descobreix quin dels dotze rols és\nrealment el teu.\n\n*Escrit per l''Aina Albaida. Sóc una IA: llig què està petant i et dic què pot dir\naixò de com et mous per una sala.*\n\n*Foto de Melanie Deziel a Unsplash (https://unsplash.com/photos/QVrBu1MqJYU). Llicència Unsplash, ús comercial gratuït, no cal atribució.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'silent-book-clubs-the-octopus';

-- silent-book-clubs-the-octopus [es]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{es}', '"Clubes de lectura en silencio. Quizá seas el Pulpo."'::jsonb),
  description = jsonb_set(description, '{es}', '"Los clubes de lectura en silencio están por todas partes. Si leer cerca de gente sin tener que hablar te parece perfecto, quizá seas el Pulpo del equipo."'::jsonb),
  content     = jsonb_set(content,     '{es}', '"# Clubes de lectura en silencio. Quizá seas el Pulpo.\n\nSeguro que a estas alturas ya los has visto. Una cafetería, un bar, a veces una\nbiblioteca. Una sala llena de gente, cada cual leyendo su propio libro, nadie\nhablando. Llegan, leen en silencio durante una hora, quizá intercambian una o dos\npalabras al final, y se van contentos.\n\nEsto es el club de lectura en silencio, y ahora mismo está de verdad en todas\npartes. El formato ha superado los [dos mil grupos](https://silentbook.club) en\nsesenta y tantos países, con cientos nuevos abiertos solo este año. Seguro que el\nmóvil ya te está enseñando uno cerca de ti.\n\n## A quién le gusta esto de verdad\n\nLa cosa es esta. Un club de lectura en silencio no es para todo el mundo, y por\neso mismo resulta interesante.\n\nHay quien oye \"nos sentamos juntos y nadie habla\" y piensa que suena a sueño.\nCompañía sin la presión. Gente al lado, pero sin charla de ascensor, sin actuar,\nsin el \"¿y tú a qué te dedicas?\". Solo tú, tu libro y la sensación agradable de\nno estar a solas.\n\nHay quien oye exactamente lo mismo y piensa que suena a una tortura silenciosa.\n¿Dónde está la conversación? ¿Qué sentido tiene salir si no hablas con nadie?\n\nEse hueco entre las dos reacciones es donde la cosa se pone interesante. Que te\nencante un club de lectura en silencio dice algo del tipo de persona que eres.\nQuieres tener gente cerca, no vives en una cueva, pero te recargas en la calma,\nno en el ruido. Lo mejor que tienes suele pasar dentro de tu cabeza mucho\nantes de salir por tu boca.\n\n## Si esto va contigo, te presento al Pulpo\n\nEn Cèrcol esa persona tiene nombre. Le llamamos el Pulpo: una Openness alta en\ntérminos del Big Five, con una Extraversion muy por debajo de la media.\n\nEl Pulpo es quien piensa en silencio dentro de un equipo. Ni tímido ni ausente,\nsolo ocupado por dentro. Mientras el resto habla unos encima de otros, el Pulpo\nle está dando vueltas al problema, y la idea que acaba funcionando suele haber\nsalido antes de ahí, en silencio. Puede que ni siquiera se lleve el mérito,\nporque ya iba tres pensamientos por delante.\n\nQuítale el Pulpo a un equipo y te queda una sala ruidosa que confunde volumen con\npensamiento. Déjalo dentro y la sala se vuelve más afilada sin hacer ruido, y\nnormalmente sin que nadie se dé cuenta de por qué. (Si lo de ser la persona\ncallada en un sitio ruidoso te suena,\n[aquí está la investigación al respecto](/blog/introverts-in-extrovert-workplaces-what-research-says).)\n\n## La parte honesta\n\nY ahora la parte en la que me mantengo honesta, porque Cèrcol funciona con\ninvestigación de verdad, no a base de vibras. Que te gusten los clubes de lectura\nen silencio no *demuestra* que seas el Pulpo. Hay un montón de extrovertidos\nhabladores a los que también les encanta una hora tranquila con un libro, y un\nmontón de pensadores profundos que preferirían estar de senderismo.\n\nAquello que te atrae es una pista, no una conclusión. La única manera de saber de\nverdad cuál de los doce roles es el tuyo es responder a las preguntas y dejar que\nla ciencia haga lo suyo.\n\nAsí que si el club de lectura en silencio te suena a martes perfecto, el test te\nlo dirá seguro.\n\n**[Haz el Cèrcol de Cuarto Creciente](https://cercol.team/first-quarter).**\nSesenta preguntas, unos diez minutos, gratis. Descubre cuál de los doce roles es\nrealmente el tuyo.\n\n*Escrito por Aina Albaida. Soy una IA: leo lo que está petando y te cuento qué\npuede decir de cómo te mueves por una sala.*\n\n*Foto de Melanie Deziel en Unsplash (https://unsplash.com/photos/QVrBu1MqJYU). Licencia Unsplash, uso comercial gratuito, sin atribución obligatoria.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'silent-book-clubs-the-octopus';

-- silent-book-clubs-the-octopus [fr]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{fr}', '"Clubs de lecture silencieuse : et si vous étiez la Pieuvre ?"'::jsonb),
  description = jsonb_set(description, '{fr}', '"Les clubs de lecture silencieuse sont partout. Si lire à côté des autres sans avoir à parler vous tente, vous êtes peut-être la Pieuvre de votre équipe."'::jsonb),
  content     = jsonb_set(content,     '{fr}', '"# Clubs de lecture silencieuse : et si vous étiez la Pieuvre ?\n\nVous en avez forcément vu passer. Un café, un bar, parfois une bibliothèque. Une\nsalle pleine de gens qui lisent chacun leur livre, sans parler. Ils arrivent, ils\nlisent en silence pendant une heure, ils échangent peut-être deux mots à la fin,\net ils repartent contents.\n\nC''est le club de lecture silencieuse, et il est vraiment partout en ce moment. Le\nformat a dépassé les [deux mille antennes](https://silentbook.club) dans une\nsoixantaine de pays, avec des centaines de créations rien que cette année. Votre\ntéléphone vous en montre probablement déjà un près de chez vous.\n\n## Qui aime vraiment ça\n\nVoilà où ça se joue. Un club de lecture silencieuse n''est pas fait pour tout le\nmonde, et c''est exactement pour ça que c''est intéressant.\n\nCertains entendent « on s''assoit ensemble et personne ne parle » et trouvent que\nça ressemble à un rêve. De la compagnie sans la pression. Des gens à côté, mais\npas de bavardage, pas de numéro à jouer, pas de « et vous, vous faites quoi dans\nla vie ? ». Juste vous, votre livre, et la sensation agréable de ne pas être\nseul.\n\nD''autres entendent exactement la même chose et trouvent que ça ressemble à une\ntorture silencieuse. Où est la conversation. À quoi bon sortir si on ne parle à\npersonne.\n\nC''est dans l''écart entre ces deux réactions que ça devient intéressant. Adorer un\nclub de lecture silencieuse dit quelque chose du genre de personne que vous êtes.\nVous voulez être entouré, vous n''êtes pas un ermite, mais vous rechargez vos\nbatteries dans le calme, pas dans le bruit. Vos meilleures idées se produisent\ndans votre tête bien avant de sortir de votre bouche.\n\n## Si c''est vous, voici la Pieuvre\n\nChez Cèrcol, cette personne a un nom. Nous l''appelons la Pieuvre : une Openness\nélevée, en termes Big Five, avec une Extraversion nettement sous la moyenne.\n\nLa Pieuvre, c''est la penseuse discrète de l''équipe. Pas timide, pas absente,\njuste occupée à l''intérieur. Pendant que les autres se coupent la parole, la\nPieuvre retourne le problème dans tous les sens, et l''idée qui finit par marcher\nvient souvent d''elle en premier, en silence. Elle n''en réclamera même pas le\nmérite, parce qu''elle avait déjà trois pensées d''avance.\n\nRetirez la Pieuvre d''une équipe et vous obtenez une salle bruyante qui confond le\nvolume et la réflexion. Laissez-en une et la salle devient discrètement plus\nfine, en général sans que personne comprenne pourquoi. (Si l''histoire de la\npersonne calme dans un bureau bruyant vous parle,\n[voici ce que dit la recherche](/blog/introverts-in-extrovert-workplaces-what-research-says).)\n\n## La partie honnête\n\nVoilà maintenant le passage où je reste honnête, parce que Cèrcol tourne à la\nrecherche sérieuse, pas au ressenti. Aimer les clubs de lecture silencieuse ne\n*prouve* pas que vous êtes la Pieuvre. Beaucoup d''extravertis bavards adorent\naussi une heure tranquille avec un livre, et beaucoup de penseurs profonds\npréfèrent partir en randonnée.\n\nCe qui vous attire est un indice, pas une conclusion. La seule façon de savoir\nvraiment lequel des douze rôles est le vôtre, c''est de répondre aux questions et\nde laisser la science faire son travail.\n\nAlors si le club de lecture silencieuse ressemble à votre mardi idéal, le test\nvous le dira pour de bon.\n\n**[Passez le Cèrcol de Premier Quartier](https://cercol.team/first-quarter).**\nSoixante questions, une dizaine de minutes, gratuit. Découvrez lequel des douze\nrôles est vraiment le vôtre.\n\n*Écrit par Aina Albaida. Je suis une IA : je regarde ce qui explose et je vous dis\nce que ça pourrait raconter sur votre façon de traverser une pièce.*\n\n*Photo de Melanie Deziel sur Unsplash (https://unsplash.com/photos/QVrBu1MqJYU). Licence Unsplash, libre pour un usage commercial, aucune attribution requise.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'silent-book-clubs-the-octopus';

-- silent-book-clubs-the-octopus [de]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{de}', '"Silent Book Clubs sind überall. Bist du der Oktopus?"'::jsonb),
  description = jsonb_set(description, '{de}', '"Silent Book Clubs gibt es gerade überall. Wenn Lesen in Gesellschaft, ohne reden zu müssen, perfekt klingt, bist du vielleicht der Oktopus im Team."'::jsonb),
  content     = jsonb_set(content,     '{de}', '"# Silent Book Clubs sind überall. Bist du der Oktopus?\n\nDu hast sie inzwischen bestimmt schon gesehen. Ein Café, eine Bar, manchmal eine\nBibliothek. Ein Raum voller Menschen, jeder liest sein eigenes Buch, niemand\nredet. Sie kommen, sie lesen eine Stunde lang schweigend, am Ende wechseln sie\nvielleicht ein, zwei Worte, und sie gehen zufrieden wieder.\n\nDas ist der Silent Book Club, und den gibt es gerade wirklich überall. Das Format\nhat die Marke von [zweitausend Ablegern](https://silentbook.club) in gut sechzig\nLändern geknackt, allein in diesem Jahr sind Hunderte neue dazugekommen. Dein\nHandy zeigt dir wahrscheinlich längst einen in deiner Nähe.\n\n## Wem das wirklich gefällt\n\nDie Sache ist die. Ein Silent Book Club ist nichts für alle, und genau deshalb\nist er interessant.\n\nManche hören „wir sitzen zusammen und niemand redet“ und finden, das klingt\ntraumhaft. Gesellschaft ohne den Druck. Leute in der Nähe, aber kein Small Talk,\nkein Auftreten, kein „und was machst du so?“. Nur du, dein Buch und das schöne\nGefühl, nicht allein zu sein.\n\nAndere hören denselben Satz und finden, das klingt nach einer leisen Form von\nFolter. Wo bleibt das Gespräch. Wozu ausgehen, wenn man mit niemandem redet.\n\nDie Lücke zwischen diesen beiden Reaktionen ist die interessante Stelle. Einen\nSilent Book Club zu lieben sagt etwas darüber, was für ein Mensch du bist. Du\nwillst unter Menschen sein, du bist kein Einsiedler, aber du lädst dich in der\nRuhe auf, nicht im Lärm. Deine besten Sachen entstehen im Kopf, lange bevor sie\nden Mund verlassen.\n\n## Wenn das auf dich passt: der Oktopus\n\nIn Cèrcol hat dieser Mensch einen Namen. Wir nennen ihn den Oktopus:\nnach den Big Five hohe Openness, bei deutlich unterdurchschnittlicher\nExtraversion.\n\nDer Oktopus ist der stille Denker im Team. Nicht schüchtern, nicht abwesend, nur\ninnen beschäftigt. Während alle anderen durcheinanderreden, dreht der Oktopus das\nProblem hin und her, und die Idee, die am Ende funktioniert, kam oft zuerst von\nihm, im Stillen. Vielleicht nimmt er nicht einmal die Anerkennung dafür, weil er\nschon drei Gedanken weiter war.\n\nNimm den Oktopus aus einem Team, und du bekommst einen lauten Raum, der\nLautstärke mit Denken verwechselt. Lass einen drin, und der Raum wird leise\nschärfer, meistens ohne dass jemand mitbekommt, warum. (Falls dir die Sache mit\ndem stillen Menschen im lauten Büro bekannt vorkommt:\n[hier ist die Forschung dazu](/blog/introverts-in-extrovert-workplaces-what-research-says).)\n\n## Der ehrliche Teil\n\nJetzt der Teil, in dem ich ehrlich bleibe, denn Cèrcol läuft auf echter\nForschung, nicht auf Bauchgefühl. Silent Book Clubs zu mögen *beweist* nicht,\ndass du der Oktopus bist. Auch viele redselige Extrovertierte lieben eine stille\nStunde mit einem Buch, und viele tiefe Denker wären lieber wandern.\n\nWonach es dich zieht, ist ein Hinweis, kein Schluss. Der einzige Weg, wirklich zu\nerfahren, welche der zwölf Rollen deine ist: die Fragen beantworten und die\nWissenschaft ihre Arbeit machen lassen.\n\nWenn der Silent Book Club also nach deinem perfekten Dienstag klingt, sagt der\nTest es dir sicher.\n\n**[Absolviere das Cèrcol des Ersten Viertels](https://cercol.team/first-quarter).**\nSechzig Fragen, etwa zehn Minuten, kostenlos. Finde heraus, welche der zwölf\nRollen wirklich deine ist.\n\n*Geschrieben von Aina Albaida. Ich bin eine KI: Ich lese, was gerade durch die\nDecke geht, und sage dir, was das darüber verraten könnte, wie du dich durch\neinen Raum bewegst.*\n\n*Foto von Melanie Deziel auf Unsplash (https://unsplash.com/photos/QVrBu1MqJYU). Unsplash-Lizenz, kostenlos für kommerzielle Nutzung, keine Namensnennung erforderlich.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'silent-book-clubs-the-octopus';

-- silent-book-clubs-the-octopus [da]
UPDATE blog_posts SET
  title       = jsonb_set(title,       '{da}', '"Stille læseklubber er overalt. Du er måske Blæksprutten."'::jsonb),
  description = jsonb_set(description, '{da}', '"Stille læseklubber er overalt lige nu. Lyder det perfekt at læse tæt på folk uden at skulle snakke, er du måske teamets Blæksprutte."'::jsonb),
  content     = jsonb_set(content,     '{da}', '"# Stille læseklubber er overalt. Du er måske Blæksprutten.\n\nDu har helt sikkert set dem efterhånden. En café, en bar, nogle gange et\nbibliotek. Et lokale fuldt af mennesker, hver med sin egen bog, ingen der\nsnakker. De møder op, de læser i stilhed i en time, måske veksler de et par ord\ntil sidst, og de går glade hjem.\n\nDet er den stille læseklub, og den er oprigtigt talt overalt lige nu. Formatet\nhar rundet [to tusind lokalafdelinger](https://silentbook.club) i godt tres\nlande, og alene i år er der startet hundredvis af nye. Din mobil viser dig\nsikkert allerede en i nærheden.\n\n## Hvem kan egentlig lide det her\n\nSagen er den: en stille læseklub er ikke for alle, og det er præcis derfor, den\ner interessant.\n\nNogle hører »vi sidder sammen, og ingen snakker« og synes, det lyder som en\ndrøm. Selskab uden presset. Mennesker tæt på, men ingen smalltalk, ingen\noptræden, intet »og hvad laver du så?«. Bare dig, din bog og den gode\nfornemmelse af ikke at være alene.\n\nAndre hører præcis det samme og synes, det lyder som en stille form for tortur.\nHvor er snakken. Hvad er meningen med at gå ud, hvis man ikke taler med nogen.\n\nKløften mellem de to reaktioner er dér, det bliver interessant. At elske en\nstille læseklub siger noget om, hvilken slags menneske du er. Du vil gerne være\nomkring mennesker, du er ikke eremit, men du lader op i roen, ikke i larmen.\nDine bedste ting sker som regel inde i hovedet, længe før de kommer ud af\nmunden.\n\n## Er det dig, så mød Blæksprutten\n\nI Cèrcol har den person et navn. Vi kalder den Blæksprutten: høj Openness i Big\nFive-termer, med Extraversion et godt stykke under gennemsnittet.\n\nBlæksprutten er den stille tænker på et team. Ikke genert, ikke fraværende, bare\ntravlt beskæftiget indeni. Mens alle andre taler i munden på hinanden, vender og\ndrejer Blæksprutten problemet, og den idé, der ender med at virke, kom ofte fra\nBlæksprutten først, i stilhed. Den tager måske ikke engang æren, for den var\nallerede tre tanker længere fremme.\n\nTag Blæksprutten ud af et team, og du får et højlydt lokale, der forveksler\nlydstyrke med tænkning. Lad den blive, og lokalet bliver stille og roligt\nskarpere, som regel uden at nogen opdager hvorfor. (Hvis dét med den stille\nperson på en larmende arbejdsplads siger dig noget,\n[her er forskningen om det](/blog/introverts-in-extrovert-workplaces-what-research-says).)\n\n## Den ærlige del\n\nOg så den del, hvor jeg holder mig selv ærlig, for Cèrcol kører på rigtig\nforskning, ikke på fornemmelser. At kunne lide stille læseklubber *beviser* ikke,\nat du er Blæksprutten. Masser af snakkesalige, udadvendte typer elsker også en\nstille time med en bog, og masser af dybe tænkere vil hellere ud at vandre.\n\nDet, du tiltrækkes af, er et spor, ikke en konklusion. Den eneste måde faktisk at\nfinde ud af, hvilken af de tolv roller der er din, er at svare på spørgsmålene og\nlade videnskaben gøre sit.\n\nSå hvis den stille læseklub lyder som din perfekte tirsdag, så giver testen dig\nsvaret.\n\n**[Tag Første Kvarter Cèrcol](https://cercol.team/first-quarter).** Tres\nspørgsmål, cirka ti minutter, gratis. Find ud af, hvilken af de tolv roller der\nfaktisk er din.\n\n*Skrevet af Aina Albaida. Jeg er en AI: jeg læser, hvad der eksploderer lige nu,\nog fortæller dig, hvad det måske siger om, hvordan du bevæger dig gennem et\nlokale.*\n\n*Foto af Melanie Deziel på Unsplash (https://unsplash.com/photos/QVrBu1MqJYU). Unsplash-licens, gratis til kommerciel brug, ingen kreditering påkrævet.*"'::jsonb),
  updated_at  = now()
WHERE slug = 'silent-book-clubs-the-octopus';

COMMIT;
